-- Placement HQ v1. Apply only to a new, dedicated Supabase project.
create extension if not exists pgcrypto;
create table public.dsa_attempts (id uuid primary key default gen_random_uuid(), user_id uuid not null default auth.uid() references auth.users(id) on delete cascade, problem_title text not null check (char_length(problem_title) between 1 and 200), problem_url text, platform text not null check (platform in ('leetcode','neetcode','other')), topic text not null, difficulty text not null check (difficulty in ('easy','medium','hard')), outcome text not null check (outcome in ('independent','hint','solution','unsolved')), duration_minutes integer check (duration_minutes between 0 and 1440), is_first_attempt boolean not null default true, is_revision boolean not null default false, company_tags text[] not null default '{}', notes text, attempted_at timestamptz not null default now(), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.learning_progress (id uuid primary key default gen_random_uuid(), user_id uuid not null default auth.uid() references auth.users(id) on delete cascade, curriculum text not null check (curriculum in ('babua','system_design')), external_id text not null, title text not null, milestone text not null default 'not_started' check (milestone in ('not_started','read','understood','designed','mocked','revised')), confidence smallint not null default 0 check (confidence between 0 and 5), notes text, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique (user_id, curriculum, external_id));
create table public.applications (id uuid primary key default gen_random_uuid(), user_id uuid not null default auth.uid() references auth.users(id) on delete cascade, company_name text not null, role text not null, job_url text, status text not null default 'applied' check (status in ('saved','applied','hr_replied','oa','interview','offer','rejected','withdrawn')), referral text, applied_at date not null default current_date, next_follow_up date, notes text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.recruiters (id uuid primary key default gen_random_uuid(), user_id uuid not null default auth.uid() references auth.users(id) on delete cascade, name text not null, company_name text, email text, phone text, linkedin_url text, status text not null default 'new' check (status in ('new','contacted','replied','follow_up','closed')), next_follow_up date, notes text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.daily_goals (id uuid primary key default gen_random_uuid(), user_id uuid not null default auth.uid() references auth.users(id) on delete cascade, goal_date date not null default current_date, dsa_target smallint not null default 3 check (dsa_target between 0 and 20), design_target smallint not null default 1 check (design_target between 0 and 10), notes text, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique (user_id, goal_date));
create index dsa_attempts_user_time_idx on public.dsa_attempts (user_id, attempted_at desc);
create index dsa_attempts_user_topic_idx on public.dsa_attempts (user_id, topic, attempted_at desc);
create index applications_user_status_idx on public.applications (user_id, status, applied_at desc);
create index recruiters_user_follow_up_idx on public.recruiters (user_id, next_follow_up) where next_follow_up is not null;
create or replace function public.set_updated_at() returns trigger language plpgsql security invoker set search_path = public as $$ begin new.updated_at = now(); return new; end; $$;
create trigger dsa_attempts_updated before update on public.dsa_attempts for each row execute procedure public.set_updated_at();
create trigger learning_progress_updated before update on public.learning_progress for each row execute procedure public.set_updated_at();
create trigger applications_updated before update on public.applications for each row execute procedure public.set_updated_at();
create trigger recruiters_updated before update on public.recruiters for each row execute procedure public.set_updated_at();
create trigger daily_goals_updated before update on public.daily_goals for each row execute procedure public.set_updated_at();
alter table public.dsa_attempts enable row level security; alter table public.learning_progress enable row level security; alter table public.applications enable row level security; alter table public.recruiters enable row level security; alter table public.daily_goals enable row level security;
create policy "own dsa attempts" on public.dsa_attempts for all to authenticated using ((select auth.uid()) = user_id) with check ((select auth.uid()) = user_id);
create policy "own learning progress" on public.learning_progress for all to authenticated using ((select auth.uid()) = user_id) with check ((select auth.uid()) = user_id);
create policy "own applications" on public.applications for all to authenticated using ((select auth.uid()) = user_id) with check ((select auth.uid()) = user_id);
create policy "own recruiters" on public.recruiters for all to authenticated using ((select auth.uid()) = user_id) with check ((select auth.uid()) = user_id);
create policy "own daily goals" on public.daily_goals for all to authenticated using ((select auth.uid()) = user_id) with check ((select auth.uid()) = user_id);
grant select, insert, update, delete on public.dsa_attempts, public.learning_progress, public.applications, public.recruiters, public.daily_goals to authenticated;
alter publication supabase_realtime add table public.dsa_attempts, public.learning_progress, public.applications, public.recruiters, public.daily_goals;
